MATCH (r:River)
WHERE EXISTS { MATCH (r)-[:flowsThrough]->(:Country {name: 'Kazakhstan'}) }
   OR EXISTS { MATCH (r)-[:partOf]->(:DrainageBasin {name: 'Irtysh basin'}) }
RETURN DISTINCT r.name AS river_name

// The schema does not define any relationship between Country and Continent nodes, so we cannot filter for "Europe" specifically.
// This query returns every country together with the number of distinct continents it is linked to (expected to be 0 for all).
MATCH (c:Country)
OPTIONAL MATCH (c)-[]->(cont:Continent)
WITH c, count(DISTINCT cont) AS continentCount
RETURN c.name AS country, continentCount
